const inputData = $input.first().json;
const body = inputData.body || inputData;

let data = body.data || body;
if (Array.isArray(data)) {
  data = data[0] || {};
}

const msg = data.message || {};
const pollUpdateMsg = msg.pollUpdateMessage || {};
const pollUpdates = data.update?.pollUpdates || data.pollUpdates || [];

const pollCreationKey = pollUpdateMsg.pollCreationMessageKey 
                     || pollUpdates[0]?.pollCreationMessageKey 
                     || pollUpdates[0]?.pollUpdateMessageKey
                     || data.pollCreationMessageKey 
                     || data.update?.pollCreationMessageKey
                     || {};

// O ID DA ENQUETE DEVE VIR ESTRITAMENTE DA CHAVE DA ENQUETE, NUNCA DE UMA MENSAGEM DE TEXTO COMUM
const pollId = pollCreationKey.id 
            || data.pollMessageId
            || data.vote?.pollMessageId
            || data.pollId
            || "";

const isFromMe = !!(data.key?.fromMe || body.fromMe || data.fromMe);

const voter = isFromMe 
           ? "agente_evolution" 
           : (data.key?.participant 
           || data.participant 
           || data.sender 
           || pollUpdates[0]?.pollUpdateMessageKey?.participant
           || pollUpdateMsg.pollCreationMessageKey?.participant
           || data.key?.remoteJid 
           || "membro_equipe");

const remoteJid = data.key?.remoteJid || data.remoteJid || "120363424743503833@g.us";
const pushName = isFromMe 
               ? "Agente (Pocket)" 
               : (data.pushName || (typeof voter === 'string' && !voter.includes('@g.us') ? voter.split('@')[0] : "Membro da equipe"));

// 1. Extração profunda de todos os textos do payload
const allTexts = [];
function extractStrings(obj) {
  if (!obj) return;
  if (typeof obj === 'string') {
    allTexts.push(obj);
    return;
  }
  if (Array.isArray(obj)) {
    obj.forEach(extractStrings);
    return;
  }
  if (typeof obj === 'object') {
    if (typeof obj.conversation === 'string') allTexts.push(obj.conversation);
    if (typeof obj.text === 'string') allTexts.push(obj.text);
    if (typeof obj.body === 'string') allTexts.push(obj.body);
    for (const [k, v] of Object.entries(obj)) {
      if (k === 'jpegThumbnail' || k === 'mediaKey') continue;
      if (typeof v === 'object' || typeof v === 'string') {
        extractStrings(v);
      }
    }
  }
}
extractStrings(body);

// GUARDA ANTI-LOOP CRÍTICA: Notificações do próprio bot devem ser ignoradas para evitar loop infinito
const textoTotal = allTexts.join(" ");
if (
  textoTotal.includes("1º VOTO REGISTRADO") ||
  textoTotal.includes("DÚVIDA ENVIADA AO CLIENTE") ||
  textoTotal.includes("RESPOSTA DO CLIENTE RECEBIDA") ||
  textoTotal.includes("DECISÃO CONCLUÍDA") ||
  textoTotal.includes("DIVERGÊNCIA DE VOTOS") ||
  textoTotal.includes("AUDITORIA FINALIZADA") ||
  textoTotal.includes("AUDITORIA CONCLUÍDA") ||
  textoTotal.includes("ERRO NO WORKFLOW")
) {
  return [{
    json: {
      tipo_evento: "IGNORAR",
      ignorado: true,
      motivo: "Notificação do próprio bot (prevenção anti-loop)"
    }
  }];
}

// Localiza qualquer string que contenha /ups
const comandoDetectado = allTexts.find(t => t.toLowerCase().includes('/ups')) || "";
const textoLimpo = comandoDetectado.trim().toLowerCase();

// Classificação de comando WhatsApp
if (textoLimpo.includes("/ups")) {
  if (textoLimpo.includes("reportei") || textoLimpo.includes("reportai") || textoLimpo.includes("report")) {
    return [{
      json: {
        tipo_evento: "COMANDO_REPORTEI",
        comando: "/ups reportei",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }

  if (textoLimpo.includes("run") || textoLimpo.includes("runservice") || textoLimpo.includes("service")) {
    return [{
      json: {
        tipo_evento: "COMANDO_RUN_SERVICE",
        comando: "/ups runservice",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }

  if (textoLimpo.includes("estremoz") || textoLimpo.includes("estremo")) {
    return [{
      json: {
        tipo_evento: "COMANDO_ESTREMOZ",
        comando: "/ups estremoz",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }

  if (textoLimpo.includes("quali") || textoLimpo.includes("qualipix")) {
    return [{
      json: {
        tipo_evento: "COMANDO_QUALIPIX",
        comando: "/ups qualipix",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }


  if (textoLimpo.includes("magic") || textoLimpo.includes("magichand")) {
    return [{
      json: {
        tipo_evento: "COMANDO_MAGIC_HANDS",
        comando: "/ups magichands",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }

  if (textoLimpo.includes("endo") || textoLimpo.includes("endomarca") || textoLimpo.includes("endormaca")) {
    return [{
      json: {
        tipo_evento: "COMANDO_ENDOMARCAS",
        comando: "/ups endomarcas",
        pushName: pushName,
        voter: voter,
        remoteJid: remoteJid,
        textoOriginal: comandoDetectado
      }
    }];
  }
}

// Mensagens normais de texto sem comando /ups NUNCA são votos de enquete
const isMsgTextoComum = (data.messageType === "conversation" || data.messageType === "extendedTextMessage") && !pollUpdateMsg.pollCreationMessageKey;
if (isMsgTextoComum) {
  return [{
    json: {
      tipo_evento: "IGNORAR",
      ignorado: true,
      motivo: "Mensagem de texto comum sem comando /ups"
    }
  }];
}

// 2. Extração inteligente e robusta de voto de enquete
function normalizarOpcao(str) {
  if (!str || typeof str !== 'string') return null;
  const s = str.trim().toLowerCase();
  if (s.includes("concorrente") || s.includes("🏢") || s.includes("⚔️") || s.includes("concorr")) {
    return "🏢 Concorrente";
  }
  if (s.includes("duvida") || s.includes("dúvida") || s.includes("cliente") || s.includes("❓") || s.includes("?")) {
    return "❓ Dúvida (Enviar ao Cliente)";
  }
  if (s.includes("segmentar") || s.includes("✅")) {
    return "✅ Segmentar";
  }
  if (s.includes("negativar") || s.includes("❌")) {
    return "❌ Negativar";
  }
  if (s.includes("teste a/b") || s.includes("teste") || s.includes("⚠️")) {
    return "⚠️ Teste A/B";
  }
  return null;
}

const candidatos = [];
if (Array.isArray(data.selectedOptions)) candidatos.push(...data.selectedOptions);
if (data.selectedOption) candidatos.push(data.selectedOption);
if (Array.isArray(data.vote?.selectedOptions)) candidatos.push(...data.vote.selectedOptions);
if (data.vote?.selectedOption) candidatos.push(data.vote.selectedOption);

if (Array.isArray(pollUpdates)) {
  pollUpdates.forEach(u => {
    if (Array.isArray(u.vote?.selectedOptions)) candidatos.push(...u.vote.selectedOptions);
    if (u.vote?.selectedOption) candidatos.push(u.vote.selectedOption);
    if (Array.isArray(u.selectedOptions)) candidatos.push(...u.selectedOptions);
  });
}
if (Array.isArray(pollUpdateMsg.vote?.selectedOptions)) candidatos.push(...pollUpdateMsg.vote.selectedOptions);
if (typeof data.text === 'string') candidatos.push(data.text);
if (typeof data.body === 'string') candidatos.push(data.body);
if (typeof msg.conversation === 'string') candidatos.push(msg.conversation);
// Removido allTexts daqui para evitar falso positivo com primeira opção da enquete (Segmentar)

let opcaoVotada = "";
for (const c of candidatos) {
  const norm = normalizarOpcao(c);
  if (norm) {
    opcaoVotada = norm;
    break;
  }
}

const isEventoEnquete = body.event?.toLowerCase().includes("poll")
                     || body.event?.toLowerCase().includes("update")
                     || data.messageType === "pollUpdateMessage"
                     || data.messageType === "pollCreationMessage"
                     || !!pollUpdateMsg.pollCreationMessageKey
                     || pollUpdates.length > 0;

if (isEventoEnquete && pollId && opcaoVotada) {
  return [{
    json: {
      tipo_evento: "VOTO_ENQUETE",
      ignorado: false,
      poll_id: pollId,
      opcao_votada: opcaoVotada,
      voter: voter,
      voter_name: pushName,
      pushName: pushName,
      is_from_me: isFromMe,
      remoteJid: remoteJid
    }
  }];
}

// Qualquer outro evento é registrado como IGNORAR
return [{
  json: {
    tipo_evento: "IGNORAR",
    ignorado: true,
    motivo: "Mensagem ou evento sem comando /ups e sem voto de enquete",
    evento_tipo: body.event || inputData.event || "desconhecido"
  }
}];

