const items = $input.all();
const textoParaIA = JSON.stringify(items.map(i => i.json));
return {
  json: {
    meu_texto_pronto: textoParaIA
  }
};

const item = $input.first();
let rawText = item.json.output || item.json.text || item.json.response || "";

rawText = rawText.replace(/\`\`\`json/gi, "")
                 .replace(/\`\`\`/gi, "")
                 .replace(/^json/gi, "")
                 .replace(/\\\\n/g, " ")
                 .trim();

function extrairJSON(texto) {
  const inicio = texto.indexOf('[');
  const fim = texto.lastIndexOf(']');
  if (inicio === -1 || fim === -1) {
    const inicioObj = texto.indexOf('{');
    const fimObj = texto.lastIndexOf('}');
    if (inicioObj !== -1 && fimObj !== -1) {
      return [JSON.parse(texto.substring(inicioObj, fimObj + 1))];
    }
    throw new Error("Formato JSON não reconhecido");
  }
  return JSON.parse(texto.substring(inicio, fim + 1));
}

function normalizar(str) {
  return String(str || '')
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\\u0300-\\u036f]/g, "")
    .replace(/[^a-z0-9]/g, " ")
    .replace(/\\s+/g, " ")
    .trim();
}

try {
  let dados = extrairJSON(rawText);
  if (!Array.isArray(dados)) dados = [dados];

  const duvidas = dados.filter(linha => {
    const d = String(linha["DUVIDA"] || "").trim();
    const s = String(linha["SEGMENTAR"] || "").trim();
    const n = String(linha["NEGATIVAR"] || "").trim();
    if (s.includes("✅") || n.includes("❌")) return false;
    if (!d.includes("❓") && !d.includes("?")) return false;

    // GUARD-RAIL: Se o termo corresponder à palavra-chave ou for intenção legítima sem negativa, não é dúvida
    const termo = normalizar(linha["Termo de pesquisa"] || linha["Termo"]);
    const kw = normalizar(linha["Palavra-chave"] || linha["Palavra_Chave"]);

    const termosNegativos = ["job", "hiring", "salary", "pay", "work", "career", "employment", "vagas", "trabalho", "how to", "diy", "tips", "vacuum", "mop", "detergent", "walmart", "craigslist"];
    const temNegativo = termosNegativos.some(t => termo.includes(t));

    if (termo && kw && !temNegativo) {
      if (termo === kw || termo.includes(kw) || kw.includes(termo)) {
        return false;
      }
    }

    return true;
  }).map(linha => ({
    "Campanha": linha["Campanha"] || "Magic Hands",
    "Grupo de anúncios": linha["Grupo de anúncios"] || linha["Grupo_Anuncio"] || "Magic Hands",
    "Palavra-chave": linha["Palavra-chave"] || linha["Palavra_Chave"] || "N/A",
    "Termo de pesquisa": linha["Termo de pesquisa"] || linha["Termo"] || "N/A",
    "Conversoes": String(linha["Conversões"] || linha["Conversoes"] || "0"),
    "Impressoes": String(linha["Impr."] || linha["Impressoes"] || linha["Impressões"] || "0"),
    "Observacao": linha["Observacao"] || "Validar pertinência para Magic Hands",
    "Cliente": "Magic Hands",
    "Cliente_JID": "120363427648562835@g.us"
  }));

  // Atualiza contador de dúvidas no staticData global
  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Magic Hands"] = staticData.stats["Magic Hands"] || { totalDuvidas: 0, erros: [], listaDuvidas: [] };
  staticData.stats["Magic Hands"].totalDuvidas = (staticData.stats["Magic Hands"].totalDuvidas || 0) + duvidas.length;
  staticData.stats["Magic Hands"].listaDuvidas = staticData.stats["Magic Hands"].listaDuvidas || [];
  staticData.stats["Magic Hands"].listaDuvidas.push(...duvidas);

  return [{
    json: {
      tem_duvidas: duvidas.length > 0,
      total_duvidas: duvidas.length,
      lista_duvidas: duvidas
    }
  }];
} catch (e) {
  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Magic Hands"] = staticData.stats["Magic Hands"] || { totalDuvidas: 0, erros: [] };
  staticData.stats["Magic Hands"].erros = staticData.stats["Magic Hands"].erros || [];
  staticData.stats["Magic Hands"].erros.push(e.message);

  return [{
    json: {
      tem_duvidas: false,
      total_duvidas: 0,
      lista_duvidas: [],
      erro: e.message
    }
  }];
}

