    const termosNegativos = ["exame", "clinica", "agendar", "dor", "doi", "preparo", "sedacao", "jejum", "gratis", "emprego", "vaga", "salario"];
    const temNegativo = termosNegativos.some(t => termo.includes(t));

    // Se o termo bater com a palavra-chave ou tiver sobreposição e sem termos negativos
    if (termo && kw && !temNegativo) {
      if (termo === kw || termo.includes(kw) || kw.includes(termo)) {
        return false; // É SEGMENTAR legítimo, não envia para enquete de dúvida
      }
    }

    // Se o comentário da IA tiver resquício de falso positivo (Baixo Conteúdo ou Peças vs Equipamento)
    if (obs.includes("baixo conteudo") || obs.includes("pecas vs equipamento") || obs.includes("pecas vs") || obs.includes("peca de reposicao")) {
      const termosCore = ["endoscop", "bocal", "bocais", "otica", "4mm", "torre", "fibroscop", "colonoscop", "gastroscop", "video"];
      if (termosCore.some(tc => termo.includes(tc) || kw.includes(tc))) {
        return false;
      }
    }

    return true;
  }).map(linha => ({
    "Campanha": linha["Campanha"] || "Endomarcas",
    "Grupo de anúncios": linha["Grupo de anúncios"] || linha["Grupo_Anuncio"] || "Endomarcas",
    "Palavra-chave": linha["Palavra-chave"] || linha["Palavra_Chave"] || "N/A",
    "Termo de pesquisa": linha["Termo de pesquisa"] || linha["Termo"] || "N/A",
    "Conversoes": String(linha["Conversões"] || linha["Conversoes"] || "0"),
    "Impressoes": String(linha["Impr."] || linha["Impressoes"] || "0"),
    "Observacao": linha["Observacao"] || "Validar pertinência para Endomarcas",
    "Cliente": "Endomarcas",
    "Cliente_JID": "120363407305667257@g.us"
  }));

  // Atualiza contador de dúvidas no staticData global
  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Endomarcas"] = staticData.stats["Endomarcas"] || { totalDuvidas: 0, erros: [], listaDuvidas: [] };
  staticData.stats["Endomarcas"].totalDuvidas = (staticData.stats["Endomarcas"].totalDuvidas || 0) + duvidas.length;
  staticData.stats["Endomarcas"].listaDuvidas = staticData.stats["Endomarcas"].listaDuvidas || [];
  staticData.stats["Endomarcas"].listaDuvidas.push(...duvidas);

  return [{
    json: {
      tem_duvidas: duvidas.length > 0,
      total_duvidas: duvidas.length,
      lista_duvidas: duvidas
    }
  }];
} catch (e) {
  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Endomarcas"] = staticData.stats["Endomarcas"] || { totalDuvidas: 0, erros: [] };
  staticData.stats["Endomarcas"].erros = staticData.stats["Endomarcas"].erros || [];
  staticData.stats["Endomarcas"].erros.push(e.message);

  return [{
    json: {
      tem_duvidas: false,
      total_duvidas: 0,
      lista_duvidas: [],
      erro: e.message
    }
  }];
}

