parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
staticData.mapaEnquetes = staticData.mapaEnquetes || {};

const itemsEnquete = $input.all();
const duvidasOriginais = $('Desmembrar Dúvidas (Endomarcas)').all();

for (let i = 0; i < itemsEnquete.length; i++) {
  const item = itemsEnquete[i].json;

  const pollId = item.key?.id || item.id || item.messageId;
  const d = duvidasOriginais[i]?.json;

  if (pollId && d) {
    staticData.mapaEnquetes[pollId] = {
      termo: d['Termo de pesquisa'] || 'Termo em auditoria',
      palavra_chave: d['Palavra-chave'] || 'N/A',
      comentario: d['Observacao'] || 'Validar intenção comercial com a equipe',
      campanha: d['Campanha'] || 'Endomarcas',
      grupo: d['Grupo de anúncios'] || 'Endomarcas',
      cliente: 'Endomarcas',
      cliente_jid: '120363407305667257@g.us'
    };
  }
}

return [{ json: { loop: true } }];

const inputData = $input.first().json;

// Se já veio pré-processado pelo Roteador Evolution
if (inputData.poll_id && inputData.opcao_votada) {
  return [{
    json: {
      ignorado: false,
      poll_id: inputData.poll_id,
      opcao_votada: inputData.opcao_votada,
      voter: inputData.voter || "membro_equipe",
      voter_name: inputData.voter_name || inputData.pushName || "Membro da equipe",
      remoteJid: inputData.remoteJid || "120363424743503833@g.us",
      is_from_me: !!inputData.is_from_me
    }
  }];
}

const body = inputData.body || inputData;
let data = body.data || body;
if (Array.isArray(data)) {
  data = data[0] || {};
}

const msg = data.message || {};
const pollUpdateMsg = msg.pollUpdateMessage || {};
const pollUpdates = data.update?.pollUpdates || data.pollUpdates || [];

const pollCreationKey = pollUpdateMsg.pollCreationMessageKey 
                     || pollUpdates[0]?.pollCreationMessageKey 
                     || pollUpdates[0]?.pollUpdateMessageKey
                     || data.pollCreationMessageKey 
                     || data.update?.pollCreationMessageKey
                     || {};

const pollId = pollCreationKey.id 
            || data.pollMessageId
            || data.vote?.pollMessageId
            || data.pollId
            || data.key?.id 
            || data.messageId 
            || "";

const isFromMe = !!(data.key?.fromMe || body.fromMe || data.fromMe);

const voter = isFromMe 
           ? "agente_evolution" 
           : (data.key?.participant 
           || data.participant 
           || data.sender 
           || pollUpdates[0]?.pollUpdateMessageKey?.participant
           || pollUpdateMsg.pollCreationMessageKey?.participant
           || data.key?.remoteJid 
           || "membro_equipe");

const voterName = isFromMe 
                ? "Agente (Pocket)" 
                : (data.pushName || (typeof voter === 'string' && !voter.includes('@g.us') ? voter.split('@')[0] : "Membro da equipe"));

const remoteJid = data.key?.remoteJid || data.remoteJid || "120363424743503833@g.us";

function normalizarOpcao(str) {
  if (!str || typeof str !== 'string') return null;
  const s = str.trim().toLowerCase();
  if (s.includes("concorrente") || s.includes("🏢") || s.includes("⚔️") || s.includes("concorr")) return "🏢 Concorrente";
  if (s.includes("duvida") || s.includes("dúvida") || s.includes("cliente") || s.includes("❓") || s.includes("?")) return "❓ Dúvida (Enviar ao Cliente)";
  if (s.includes("segmentar") || s.includes("✅")) return "✅ Segmentar";
  if (s.includes("negativar") || s.includes("❌")) return "❌ Negativar";
  if (s.includes("teste a/b") || s.includes("teste") || s.includes("⚠️")) return "⚠️ Teste A/B";
  return null;
}

const candidatos = [];
if (Array.isArray(data.selectedOptions)) candidatos.push(...data.selectedOptions);
if (data.selectedOption) candidatos.push(data.selectedOption);
if (Array.isArray(data.vote?.selectedOptions)) candidatos.push(...data.vote.selectedOptions);
if (data.vote?.selectedOption) candidatos.push(data.vote.selectedOption);

if (Array.isArray(pollUpdates)) {
  pollUpdates.forEach(u => {
    if (Array.isArray(u.vote?.selectedOptions)) candidatos.push(...u.vote.selectedOptions);
    if (u.vote?.selectedOption) candidatos.push(u.vote.selectedOption);
    if (Array.isArray(u.selectedOptions)) candidatos.push(...u.selectedOptions);
  });
}
if (Array.isArray(pollUpdateMsg.vote?.selectedOptions)) candidatos.push(...pollUpdateMsg.vote.selectedOptions);
if (pollUpdateMsg.vote?.selectedOption) candidatos.push(pollUpdateMsg.vote.selectedOption);

if (typeof data.text === 'string') candidatos.push(data.text);
if (typeof data.body === 'string') candidatos.push(data.body);
if (typeof msg.conversation === 'string') candidatos.push(msg.conversation);

let opcaoVotada = "";
for (const c of candidatos) {
  const norm = normalizarOpcao(c);
  if (norm) {
    opcaoVotada = norm;
    break;
  }
}

if (!pollId || !opcaoVotada) {
  return [{ json: { ignorado: true, motivo: "Evento sem voto ou sem ID de enquete", poll_id: pollId, opcao_votada: opcaoVotada } }];
}

return [{
  json: {
    ignorado: false,
    poll_id: pollId,
    opcao_votada: opcaoVotada,
    voter: voter,
    voter_name: voterName,
    remoteJid: remoteJid,
    is_from_me: isFromMe
  }
}];

