const dadosVoto = $('1. Extrair ID e Voto').first().json;
if (dadosVoto.ignorado) {
  return [{ json: { ignorado: true, motivo: dadosVoto.motivo } }];
}

const pollId = dadosVoto.poll_id;
const isFromMe = dadosVoto.voter === "agente_evolution" || !!dadosVoto.is_from_me;
const voter = isFromMe ? "agente_evolution" : dadosVoto.voter;
const voterName = isFromMe ? "Agente (Pocket)" : (dadosVoto.voter_name || dadosVoto.pushName || (typeof voter === 'string' && !voter.includes('@g.us') ? voter.split('@')[0] : "Membro"));
const remoteJidVoto = dadosVoto.remoteJid || "120363424743503833@g.us";

// 1. Dados retornados diretamente da Evolution API (Find Messages)
// A. Mensagem de Criação da Enquete (buscada diretamente por key.id)
let creationJson = {};
try {
  creationJson = $('2. Buscar Criacao na Evolution').first().json;
} catch (e) {
  creationJson = {};
}
const creationRecords = creationJson.messages?.records || creationJson.records || [];

// B. Mensagens de Atualização / Votos na Evolution
let votesJson = {};
try {
  votesJson = $input.first().json;
} catch (e) {
  votesJson = {};
}
const records = votesJson.messages?.records || votesJson.records || [];

// Localizar a mensagem de criação: primeiro nos records dedicados, depois nos records gerais
const creationMsg = creationRecords.find(r => r.key?.id === pollId) 
                 || creationRecords[0]
                 || records.find(r => r.key?.id === pollId);

const rawName = creationMsg?.message?.pollCreationMessageV3?.name 
             || creationMsg?.message?.pollCreationMessage?.name 
             || "";

const pollRemoteJid = creationMsg?.key?.remoteJid || remoteJidVoto;

let termoEvo = "";
let comentarioEvo = "";
let clienteEvo = "";
let campEvo = "";
let grupoEvo = "";
let kwEvo = "";

if (rawName) {
  const matchTermo = rawName.match(/Termo:\*?\s*["“]?([^"”\n\r]+)["”]?/i);
  if (matchTermo) termoEvo = matchTermo[1].trim();

  const matchComentario = rawName.match(/(?:Coment[áa]rio|Obs):\*?\s*([^\n\r]+)/i);
  if (matchComentario) comentarioEvo = matchComentario[1].trim();

  const matchCamp = rawName.match(/Camp(?:anha)?:\*?\s*([^\n\r]+)/i);
  if (matchCamp) campEvo = matchCamp[1].trim();

  const matchGrupo = rawName.match(/Grupo(?:\s*de\s*an[úu]ncios)?:\*?\s*([^\n\r]+)/i);
  if (matchGrupo) grupoEvo = matchGrupo[1].trim();

  const matchKw = rawName.match(/(?:Palavra-chave|KW):\*?\s*([^\n\r]+)/i);
  if (matchKw) kwEvo = matchKw[1].trim();

  const matchCliente = rawName.match(/Cliente:\*?\s*([^\n\r]+)/i);
  if (matchCliente) {
    const c = matchCliente[1].trim().toLowerCase();
    if (c.includes('reportei') || c.includes('report')) clienteEvo = 'Reportei';
    else if (c.includes('run') || c.includes('service')) clienteEvo = 'Run Service';
    else if (c.includes('quali')) clienteEvo = 'Qualipix';
    else if (c.includes('endo')) clienteEvo = 'Endomarcas';
    else if (c.includes('estremoz')) clienteEvo = 'Estremoz';
    else if (c.includes('magic') || c.includes('hands')) clienteEvo = 'Magic Hands';
    else clienteEvo = matchCliente[1].trim();
  }
}

// 2. Identificação por grupo de origem (se veio diretamente de um grupo de cliente ou equipe)
if (!clienteEvo) {
  if (pollRemoteJid.includes("120363412429579994") || remoteJidVoto.includes("120363412429579994") || pollRemoteJid.includes("120363435040456024") || remoteJidVoto.includes("120363435040456024")) {
    clienteEvo = "Reportei";
  } else if (pollRemoteJid.includes("120363415485750352") || remoteJidVoto.includes("120363415485750352")) {
    clienteEvo = "Run Service";
  } else if (pollRemoteJid.includes("120363402801713988") || remoteJidVoto.includes("120363402801713988")) {
    clienteEvo = "Qualipix";
  } else if (pollRemoteJid.includes("120363407305667257") || remoteJidVoto.includes("120363407305667257")) {
    clienteEvo = "Endomarcas";
