    clienteEvo = "Estremoz";
  } else if (pollRemoteJid.includes("120363427648562835") || remoteJidVoto.includes("120363427648562835") || pollRemoteJid.includes("120363412774496440") || remoteJidVoto.includes("120363412774496440")) {
    clienteEvo = "Magic Hands";
