}

// 3. Identificação robusta por Campanha, Grupo de Anúncios, Palavra-Chave e Termo
if (!clienteEvo) {
  const fullText = (rawName + " " + campEvo + " " + grupoEvo + " " + kwEvo + " " + termoEvo).toLowerCase();

  // F. Reportei: dashboards, relatórios de marketing, automação, looker, metricool, mlabs
  if (
    fullText.includes("reportei") ||
