    especialistasJid = infoMemoria.especialistas_jid;
  } else {
    especialistasJid = "120363424743503833@g.us";
  }
}

const grupoDestino = especialistasJid;

// Atualiza cache em memória para garantir consistência
staticData.mapaEnquetes[pollId] = {
  termo: termoReal,
  palavra_chave: kwReal,
  campanha: campReal,
  grupo: grupoReal,
  comentario: comentarioReal,
  cliente: clienteReal,
  cliente_jid: clienteJid,
  especialistas_jid: grupoDestino
};

function normalizarOpcao(str) {
  if (!str || typeof str !== 'string') return "";
  const s = str.trim().toLowerCase();
  if (s.includes("concorrente") || s.includes("🏢") || s.includes("⚔️") || s.includes("concorr")) return "🏢 Concorrente";
  if (s.includes("duvida") || s.includes("dúvida") || s.includes("cliente") || s.includes("❓") || s.includes("?")) return "❓ Dúvida (Enviar ao Cliente)";
  if (s.includes("segmentar") || s.includes("✅")) return "✅ Segmentar";
  if (s.includes("negativar") || s.includes("❌")) return "❌ Negativar";
  if (s.includes("teste a/b") || s.includes("teste") || s.includes("⚠️")) return "⚠️ Teste A/B";
  return str.trim();
}

// 5. Checagem de Origem: Voto em Grupo de Cliente vs Voto da Equipe Interna
// Grupos de especialistas (equipe): requerem 2 votos e consenso
const isSpecialistsGroup = remoteJidVoto.includes("120363424743503833") 
                        || remoteJidVoto.includes("120363435040456024")
                        || (infoMemoria.especialistas_jid && remoteJidVoto.includes(infoMemoria.especialistas_jid.replace('@g.us', '')));

// Grupos de clientes: 1 único voto é soberano
const isClientGroup = !isSpecialistsGroup && (
     remoteJidVoto.includes("120363412429579994") // Reportei
  || remoteJidVoto.includes("120363415485750352") // Run Service
  || remoteJidVoto.includes("120363407305667257") // Endomarcas
  || remoteJidVoto.includes("120363427648562835") // Magic Hands
  || remoteJidVoto.includes("120363402801713988") // Qualipix
  || remoteJidVoto.includes("120363406729550086") // Estremoz
  || (infoMemoria.cliente_jid && remoteJidVoto.includes(infoMemoria.cliente_jid.replace('@g.us', '')))
);

if (isClientGroup) {
  // O voto veio de um grupo de cliente. A decisão do cliente é soberana com apenas 1 voto.
  staticData.enquetes[pollId] = staticData.enquetes[pollId] || { concluido: false };
  if (staticData.enquetes[pollId].concluido) {
    return [{ json: { ignorado: true, motivo: "Resposta do cliente já processada anteriormente", termo: termoReal, cliente: clienteReal } }];
  }
  staticData.enquetes[pollId].concluido = true;

  const opcaoNorm = normalizarOpcao(dadosVoto.opcao_votada);

  return [{
    json: {
      origem: "CLIENTE",
      consenso_atingido: true,
      divergencia: false,
      poll_id: pollId,
      opcao_vencedora: opcaoNorm,
      total_votos: 1,
      acao: "RESPOSTA_CLIENTE",
      termo: termoReal,
      palavra_chave: kwReal,
      campanha: campReal,
      grupo: grupoReal,
      comentario: comentarioReal,
      cliente: clienteReal,
      cliente_jid: clienteJid,
      voter_name: voterName,
      grupo_destino: grupoDestino
    }
  }];
}

// 6. Reconciliação dos votos da equipe persistidos no banco da Evolution API
const ultimosVotos = new Map();

const updatesEvolution = records
  .filter(r => r.message?.pollUpdateMessage?.pollCreationMessageKey?.id === pollId)
  .sort((a, b) => (a.messageTimestamp || 0) - (b.messageTimestamp || 0));

updatesEvolution.forEach(u => {
  const part = u.key?.participant || u.participant || u.pushName;
  const name = u.pushName || part;
  const opts = u.message?.pollUpdateMessage?.vote?.selectedOptions || [];
  if (opts.length > 0) {
    const norm = normalizarOpcao(opts[0]);
    if (norm) {
      ultimosVotos.set(part, { id: part, name: name, opcao: norm });
    }
  } else {
    ultimosVotos.delete(part);
  }
});

// Inclui o voto atual que acabou de chegar no webhook
if (dadosVoto.voter && dadosVoto.opcao_votada) {
  const norm = normalizarOpcao(dadosVoto.opcao_votada);
  if (norm) {
    ultimosVotos.set(voter, { id: voter, name: voterName, opcao: norm });
  }
}

// Agrupa votos consolidados por opção
const votosPorOpcao = {};
for (const [voterKey, vData] of ultimosVotos.entries()) {
  votosPorOpcao[vData.opcao] = votosPorOpcao[vData.opcao] || [];
  votosPorOpcao[vData.opcao].push(vData);
}

// 7. Controle de Conclusão para Evitar Duplo Disparo
staticData.enquetes[pollId] = staticData.enquetes[pollId] || {
  concluido: false,
  ultimaDivergencia: ""
};

const registro = staticData.enquetes[pollId];
if (registro.concluido) {
  return [{ json: { ignorado: true, motivo: "Enquete já decidida anteriormente", termo: termoReal, cliente: clienteReal } }];
}

// 8. Verifica Consenso da Equipe (2 votos na mesma opção)
const VOTOS_NECESSARIOS = 2;
let opcaoVencedora = null;
let totalVotosVencedora = 0;

for (const [opt, lista] of Object.entries(votosPorOpcao)) {
  if (lista.length >= VOTOS_NECESSARIOS) {
    opcaoVencedora = opt;
    totalVotosVencedora = lista.length;
    break;
  }
}

if (opcaoVencedora) {
  registro.concluido = true;
  const isDuvida = opcaoVencedora.includes("Dúvida") || opcaoVencedora.includes("❓") || opcaoVencedora.includes("Cliente");

  // GUARD-RAIL CRÍTICO: Se for dúvida para cliente mas o JID do cliente não existe, não despacha para cliente aleatório!
  if (isDuvida && !clienteJid) {
    return [{
      json: {
        origem: "EQUIPE",
        consenso_atingido: true,
        divergencia: false,
        poll_id: pollId,
        opcao_vencedora: opcaoVencedora,
        total_votos: totalVotosVencedora,
        acao: "DECISAO_INTERNA",
        termo: termoReal,
        palavra_chave: kwReal,
        campanha: campReal,
        grupo: grupoReal,
        comentario: comentarioReal,
        cliente: clienteReal || "Desconhecido",
        cliente_jid: "",
        aviso: "Bloqueado envio ao cliente: JID do cliente não identificado com segurança.",
        grupo_destino: grupoDestino
      }
    }];
  }

  return [{
    json: {
      origem: "EQUIPE",
      consenso_atingido: true,
      divergencia: false,
      poll_id: pollId,
      opcao_vencedora: opcaoVencedora,
      total_votos: totalVotosVencedora,
      acao: isDuvida ? "ENVIAR_CLIENTE" : "DECISAO_INTERNA",
      termo: termoReal,
      palavra_chave: kwReal,
      campanha: campReal,
      grupo: grupoReal,
      comentario: comentarioReal,
      cliente: clienteReal,
      cliente_jid: clienteJid,
      grupo_destino: grupoDestino
    }
  }];
}

// 9. Verifica Divergência da Equipe (2 ou mais opções distintas com votos)
const opcoesAtivas = Object.entries(votosPorOpcao).filter(([opt, lista]) => lista.length > 0);

if (opcoesAtivas.length >= 2) {
  const linhasDivergencia = [];
  opcoesAtivas.forEach(([opt, lista]) => {
    const nomes = lista.map(v => v.name || v.id || "Membro").join(", ");
    linhasDivergencia.push(`👤 *${nomes}:* escolheu *${opt}*`);
  });
  const detalhesDivergencia = linhasDivergencia.join("\n");

  const estadoAtual = opcoesAtivas
    .map(([opt, lista]) => `${opt}:${lista.map(v => v.id || v).sort().join(',')}`)
    .sort()
    .join('|');

  if (registro.ultimaDivergencia !== estadoAtual) {
    registro.ultimaDivergencia = estadoAtual;
    return [{
      json: {
        origem: "EQUIPE",
        consenso_atingido: false,
        divergencia: true,
        poll_id: pollId,
        termo: termoReal,
        palavra_chave: kwReal,
        campanha: campReal,
        grupo: grupoReal,
        cliente: clienteReal,
        detalhes_divergencia: detalhesDivergencia,
        total_opcoes_divergentes: opcoesAtivas.length,
        grupo_destino: grupoDestino
      }
    }];
  }
}

const opcaoAtualNorm = normalizarOpcao(dadosVoto.opcao_votada);
const votosDessaOpcao = votosPorOpcao[opcaoAtualNorm]?.length || 1;

return [{
  json: {
    origem: "EQUIPE",
    consenso_atingido: false,
    divergencia: false,
    poll_id: pollId,
    opcao_votada: opcaoAtualNorm,
    votos_atuais: votosDessaOpcao,
    voter_name: voterName,
    termo: termoReal,
    palavra_chave: kwReal,
    campanha: campReal,
    grupo: grupoReal,
    cliente: clienteReal,
    mensagem: `1º voto registrado por ${voterName}. Aguardando 2º voto.`,
    grupo_destino: grupoDestino
  }
}];

