    "Impressoes": String(linha["Impr."] || linha["Impressoes"] || "0"),
    "Observacao": linha["Observacao"] || "Validar pertinência para Estremoz",
    "Cliente": "Estremoz",
    "Cliente_JID": "120363406729550086@g.us"
  }));

  const staticData = $getWorkflowStaticData('global');
  staticData.stats = staticData.stats || {};
  staticData.stats["Estremoz"] = staticData.stats["Estremoz"] || { totalDuvidas: 0, erros: [], listaDuvidas: [] };
  staticData.stats["Estremoz"].totalDuvidas = (staticData.stats["Estremoz"].totalDuvidas || 0) + duvidas.length;
  staticData.stats["Estremoz"].listaDuvidas = staticData.stats["Estremoz"].listaDuvidas || [];
  staticData.stats["Estremoz"].listaDuvidas.push(...duvidas);

  return [{
    json: {
      tem_duvidas: duvidas.length > 0,
      total_duvidas: duvidas.length,
      lista_duvidas: duvidas
    }
  }];
} catch (e) {
  const staticData = $getWorkflowStaticData('global');
